from pathlib import Path
import json,re
from urllib.parse import unquote,urlsplit
from html import unescape
root=Path('site');docs={p.name.lower():p.read_text(encoding='utf-8') for p in root.glob('*.html')}
def word(name,seen=None):
 name=unquote(urlsplit(name).path).split('/')[-1].lower();seen=set() if seen is None else seen
 if name not in docs or name in seen:return None
 seen.add(name);s=docs[name]
 redirect=re.search(r'url=([^"\s>]+)',s,re.I)
 if redirect:return word(redirect[1],seen)
 if 'class="tema"' not in s:return None
 return unescape(re.search(r'<h1>(.*?)</h1>',s,re.S)[1]).strip().lower()
pairs=set();valid={word(n) for n in docs}-{None}
for name,s in docs.items():
 source=word(name)
 if not source or 'class="tema"' not in s:continue
 for section in re.findall(r'<section\b[^>]*>(.*?)</section>',s,re.S):
  for target in re.findall(r'href="([^"]+)"',section):
   dest=word(target)
   if dest and dest!=source:pairs.add(tuple(sorted((source,dest))))
w=json.loads(Path('words.json').read_text(encoding='utf-8'));r=json.loads(Path('result.json').read_text(encoding='utf-8'))
assert valid==set(w)
