from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import unquote,urlsplit
import json,re
class Page(HTMLParser):
 def __init__(self,text):
  super().__init__();self.word='';self.theme='';self.links=[];self.section=None;self.capture=None;self.redirect=None;self.feed(text)
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if tag=='h1':self.capture='word'
  if tag=='p' and a.get('class')=='tema':self.capture='theme'
  if tag=='section':self.section=a.get('id')
  if tag=='a' and self.section in ('sinonimos','analogas'):self.links.append(a.get('href',''))
  if tag=='meta' and a.get('http-equiv','').lower()=='refresh':self.redirect=re.split('url=',a.get('content',''),flags=re.I)[-1].strip()
 def handle_endtag(self,tag):
  if tag in ('h1','p'):self.capture=None
  if tag=='section':self.section=None
 def handle_data(self,s):
  if self.capture:setattr(self,self.capture,getattr(self,self.capture)+s)
def norm(s):return s.strip().lower()
pages={norm(p.name):Page(p.read_text(encoding='utf-8')) for p in Path('site').glob('*.html')}
def resolve(href,seen=None):
 key=norm(unquote(urlsplit(href).path).split('/')[-1]);seen=set() if seen is None else seen
 if key in seen or key not in pages:return None
 seen.add(key);p=pages[key]
 if p.redirect:return resolve(p.redirect,seen)
 return norm(p.word) if p.theme else None
words={norm(p.word):set() for p in pages.values() if p.theme}
themes={norm(p.word):p.theme.replace('Tema:','').strip() for p in pages.values() if p.theme}
missing=set();aliases={}
for name,p in pages.items():
 if p.redirect:aliases[norm(name[:-5])]=resolve(name)
 if not p.theme:continue
 w=norm(p.word)
 for href in p.links:
  v=resolve(href)
  if v and v!=w:words[w].add(v);words[v].add(w)
  elif not v:missing.add(href)
words={w:sorted(v) for w,v in sorted(words.items())}
maximum=max(map(len,words.values()));most=[w for w,v in words.items() if len(v)==maximum]
result={'words':len(words),'relations':sum(map(len,words.values()))//2,'most_connected':most}
Path('words.json').write_text(json.dumps(words,ensure_ascii=False,indent=2),encoding='utf-8')
Path('result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
Path('universe/embedded.json').write_text(json.dumps({'words':words,'themes':themes,'aliases':aliases,'result':result},ensure_ascii=False),encoding='utf-8')
print(json.dumps(result,ensure_ascii=False));print('Maximum degree:',maximum);print('Unresolved content targets:',len(missing));print('Canonical pages:',len(themes));print('Redirects:',len(aliases))
assert 'saudade' in words and 'esperança' in words['saudade']
assert 'rascunho-3' not in words and 'sobre' not in words
assert all(w in words[v] for w,vs in words.items() for v in vs)
assert sum(map(len,words.values()))==2*result['relations']
print('PASS: canonical saudade, missing/navigation exclusion, symmetric adjacency, distinct-pair count')



